# Own runner: filter code like the harness, run tests in subprocess, capture exception messages.
import subprocess, tempfile, textwrap, sys
qmap = {q['id']: q for q in mbpp}
def filter_code(code):
    try:
        tree = ast.parse(code)
    except SyntaxError:
        return None
    keep = [n for n in tree.body if isinstance(n, (ast.Import, ast.ImportFrom, ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef, ast.Assign, ast.AnnAssign))]
    return '\n'.join(ast.get_source_segment(code, n) for n in keep)

RUNNER = r'''
import sys, traceback, json
src = open(sys.argv[1]).read()
tests = json.load(open(sys.argv[2]))
g = {"__name__": "__main__"}
try:
    exec(compile(src, "sol.py", "exec"), g)
except Exception as e:
    print(json.dumps({"stage": "def", "exc": type(e).__name__, "msg": str(e)[:300]})); sys.exit()
for t in tests:
    try:
        exec(t, g)
    except AssertionError:
        print(json.dumps({"stage": "test", "exc": "AssertionError", "msg": t[:200]})); sys.exit()
    except Exception as e:
        tb = traceback.extract_tb(e.__traceback__)
        print(json.dumps({"stage": "test", "exc": type(e).__name__, "msg": str(e)[:300], "line": tb[-1].lineno if tb else None})); sys.exit()
print(json.dumps({"stage": "ok"}))
'''
open('/work/runner.py', 'w').write(RUNNER)
def my_run(code, qid, timeout=10):
