    src = (q.get('test_setup') or '') + '\n' + fc
    with tempfile.TemporaryDirectory() as td:
        open(f'{td}/s.py', 'w').write(src); json.dump(q['tests'], open(f'{td}/t.json', 'w'))
        try:
            out = subprocess.run([sys.executable, '-I', '/work/runner.py', f'{td}/s.py', f'{td}/t.json'], capture_output=True, text=True, timeout=timeout, cwd=td)
            return json.loads(out.stdout.strip().splitlines()[-1]) if out.stdout.strip() else {'stage': 'crash', 'msg': out.stderr[-300:]}
        except subprocess.TimeoutExpired:
            return {'stage': 'timeout'}
