        ids_ += list(gids); tgt += [gt] * len(gids); w += [gw / len(gids)] * len(gids)
    ids_ += protect + rand_v; tgt += [0] * (len(protect) + len(rand_v)); w += [w_prot / len(protect)] * len(protect) + [w_rand / len(rand_v)] * len(rand_v)
